## Enhanced Form Validation Components

### Base Form Field Component

```typescript
interface FormFieldProps {
  name: string;
  label: string;
  type?: 'text' | 'email' | 'number' | 'password' | 'tel';
  placeholder?: string;
  description?: string;
  required?: boolean;
  disabled?: boolean;
  validation?: ValidationRules;
  showValidation?: 'always' | 'on-blur' | 'on-submit';
  children?: React.ReactNode;
}

interface ValidationRules {
  required?: boolean | string;
  min?: number;
  max?: number;
  minLength?: number;
  maxLength?: number;
  pattern?: RegExp;
  custom?: (value: any) => string | undefined;
}

export function FormField({
  name,
  label,
  type = 'text',
  placeholder,
  description,
  required,
  disabled,
  validation,
  showValidation = 'on-blur',
  children
}: FormFieldProps) {
  const {
    register,
    formState: { errors, touchedFields },
    watch
  } = useFormContext();

  const value = watch(name);
  const error = errors[name];
  const touched = touchedFields[name];
  const [isValidating, setIsValidating] = useState(false);

  // Real-time validation with debouncing
  const debouncedValidation = useMemo(
    () => debounce(async (value) => {
      if (validation?.custom) {
        setIsValidating(true);
        const customError = await validation.custom(value);
        setIsValidating(false);
        return customError;
      }
    }, 300),
    [validation]
  );

  useEffect(() => {
    if (value && showValidation === 'always') {
      debouncedValidation(value);
    }
  }, [value, debouncedValidation, showValidation]);

  const validationState = useMemo(() => {
    if (isValidating) return 'validating';
    if (error) return 'error';
    if (touched && value && !error) return 'success';
    return 'default';
  }, [isValidating, error, touched, value]);

  const validationIcon = {
    validating: <Loader className="h-4 w-4 animate-spin" />,
    error: <AlertCircle className="h-4 w-4 text-destructive" />,
    success: <CheckCircle className="h-4 w-4 text-success" />,
    default: null
  };

  return (
    <div className="space-y-2">
      <Label htmlFor={name} className="flex items-center gap-1">
        {label}
        {required && <span className="text-destructive">*</span>}
      </Label>

      <div className="relative">
        {children || (
          <Input
            id={name}
            type={type}
            placeholder={placeholder}
            disabled={disabled}
            className={cn(
              "pr-10",
              validationState === 'error' && "border-destructive focus:border-destructive",
              validationState === 'success' && "border-success"
            )}
            {...register(name, {
              required: required && (typeof validation?.required === 'string'
                ? validation.required
                : `${label} is required`),
              min: validation?.min && {
                value: validation.min,
                message: `Minimum value is ${validation.min}`
              },
              max: validation?.max && {
                value: validation.max,
                message: `Maximum value is ${validation.max}`
              },
              minLength: validation?.minLength && {
                value: validation.minLength,
                message: `Minimum length is ${validation.minLength} characters`
              },
              maxLength: validation?.maxLength && {
                value: validation.maxLength,
                message: `Maximum length is ${validation.maxLength} characters`
              },
              pattern: validation?.pattern && {
                value: validation.pattern,
                message: 'Invalid format'
              }
            })}
          />
        )}

        {/* Validation Icon */}
        <div className="absolute right-3 top-1/2 -translate-y-1/2">
          {validationIcon[validationState]}
        </div>
      </div>

      {/* Description */}
      {description && !error && (
        <p className="text-sm text-muted-foreground">{description}</p>
      )}

      {/* Error Message */}
      {error && (
        <p
          className="text-sm text-destructive flex items-center gap-1"
          role="alert"
          aria-live="polite"
        >
          <AlertCircle className="h-3 w-3" />
          {error.message}
        </p>
      )}
    </div>
  );
}
```

