### Form Submission Enhancement

```typescript
interface EnhancedFormProps extends React.FormHTMLAttributes<HTMLFormElement> {
  onSubmit: (data: any) => Promise<void>;
  children: React.ReactNode;
  submitText?: string;
  loadingText?: string;
  resetOnSuccess?: boolean;
  showProgress?: boolean;
}

export function EnhancedForm({
  onSubmit,
  children,
  submitText = "Submit",
  loadingText = "Submitting...",
  resetOnSuccess = false,
  showProgress = false,
  ...props
}: EnhancedFormProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const methods = useForm({
    mode: 'onBlur',
    reValidateMode: 'onChange'
  });

  const { handleSubmit, reset, formState: { isValid } } = methods;

  const onSubmitHandler = async (data: any) => {
    setIsSubmitting(true);
    setSubmitError(null);
    setSubmitSuccess(false);

    try {
      await onSubmit(data);
      setSubmitSuccess(true);
      if (resetOnSuccess) {
        reset();
      }
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : 'An error occurred');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <FormProvider {...methods}>
      <form onSubmit={handleSubmit(onSubmitHandler)} {...props}>
        <div className="space-y-6">
          {children}

          {/* Submit Error */}
          {submitError && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertTitle>Submission Failed</AlertTitle>
              <AlertDescription>{submitError}</AlertDescription>
            </Alert>
          )}

          {/* Success Message */}
          {submitSuccess && (
            <Alert variant="success">
              <CheckCircle className="h-4 w-4" />
              <AlertTitle>Success!</AlertTitle>
              <AlertDescription>Your form was submitted successfully.</AlertDescription>
            </Alert>
          )}

          {/* Submit Button */}
          <div className="flex gap-3 pt-4">
            <Button
              type="submit"
              disabled={!isValid || isSubmitting}
              className="min-w-32"
            >
              {isSubmitting ? (
                <>
                  <Loader className="mr-2 h-4 w-4 animate-spin" />
                  {loadingText}
                </>
              ) : (
                submitText
              )}
            </Button>

            {showProgress && isSubmitting && (
              <div className="flex items-center text-sm text-muted-foreground">
                Processing transaction...
              </div>
            )}
          </div>
        </div>
      </form>
    </FormProvider>
  );
}
```

